"""Reconcile the inventory aggregate with the already-selected Blender horn fitting."""
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3]
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def ref(p):return dict(path=p.relative_to(ROOT).as_posix(),sha256=hashlib.sha256(p.read_bytes()).hexdigest())
def write(p,v):p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8',newline='\n')
l=read(ROOT/'evidence/conversion-ledger.json');assert l['active_entry'] is None;e=next(e for e in l['entries'] if e['id']=='ITEM-HORNS');fit=next(e for e in l['entries'] if e['id']=='FIT-YRAME-HORNS-HEAD-0');assert fit['generation_ready'];old=e['current_registration'];current=fit['current_registration'];m=read(ROOT/current['model']['path']);assert ref(ROOT/current['model']['path'])==current['model'];assert ref(ROOT/current['plate']['path'])==current['plate'];now=datetime.now(timezone.utc).isoformat();record=read(HERE/'fittings.json');assert record['fittings'][0]['registration']==current
# Briefly make the affected aggregate the sole current entry while reconciling it.
e.update(status='IN PROGRESS',generation_ready=False,current_step='verify_every_body_fitting_log');l['active_entry']=e['id'];write(ROOT/'evidence/conversion-ledger.json',l)
reason='Whole-ledger authoring dependency reconciliation found the ledger Horns aggregate still referenced pre-Blender v3 while its already-prepared v4 aggregate, fitted source and current Yrame NPC used blender-fit-v4/registered-v1. Select the existing exact v4 aggregate without changing it. Its current fitting, fixed body, actual slot/laterality, source/fit contract and existing authoring review match. The reviewed plate is reused by hash. No art regeneration, style refinement, duplicate item, runtime acceptance or gameplay change.'
e['process_log'].append(dict(timestamp=now,step='verify_every_body_fitting_log',action='Refresh stale Horns inventory aggregate to exact selected Blender fitting; retain old aggregate as history.',inputs=[old['model'],current['model']],outputs=[ref(HERE/'fittings.json'),current['plate']],review=reason,result='PASS'));e.update(status='UNFINISHED',generation_ready=True,current_step='record_item_acceptance_from_all_fittings',current_registration=dict(model=ref(HERE/'fittings.json'),plate=current['plate']),registration_summary='Exact current saved-Blender horn fitting reused; pre-Blender aggregate superseded. Native item acceptance remains pending.',known_issues=['Final native item acceptance remains pending full-set test.']);l.update(active_entry=None,updated_at=now);write(ROOT/'evidence/conversion-ledger.json',l);print('Horns aggregate now uses exact current Blender source; all156 generation flags restored, gate reconciliation continues.')
